package com.dappunq.persistence;
import com.dappunq.model.valuation.*; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="historial_valuaciones",uniqueConstraints=@UniqueConstraint(columnNames={"usuario_id","jugador_id","ventana","tipo_ejecucion"})) public class ValuationHistoryEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) @JoinColumn(name="usuario_id") UserEntity user; @ManyToOne(optional=false) @JoinColumn(name="jugador_id") PlayerEntity player; int tokens; @Column(name="valor_unitario") BigDecimal valorUnitario; @Column(name="valor_total") BigDecimal valorTotal; @Enumerated(EnumType.STRING) StrategyType estrategia; Instant ejecutadoEn=Instant.now(); String ventana; @Enumerated(EnumType.STRING) ExecutionType tipoEjecucion; protected ValuationHistoryEntity(){} public ValuationHistoryEntity(UserEntity u,PlayerEntity p,int t,BigDecimal v,StrategyType s,String w,ExecutionType x){user=u;player=p;tokens=t;valorUnitario=v;valorTotal=v.multiply(BigDecimal.valueOf(t));estrategia=s;ventana=w;tipoEjecucion=x;} public Long getId(){return id;} public UserEntity getUser(){return user;} public PlayerEntity getPlayer(){return player;} public int getTokens(){return tokens;} public BigDecimal getValorUnitario(){return valorUnitario;} public BigDecimal getValorTotal(){return valorTotal;} public StrategyType getEstrategia(){return estrategia;} public Instant getEjecutadoEn(){return ejecutadoEn;} public ExecutionType getTipoEjecucion(){return tipoEjecucion;} }
